entries[216624] = { ["name"] = "Mal der Arroganz", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Angreifer erhalten ein 'Mal der Arroganz', das 10 Sek. lang alle 2 Sek. Schattenschaden verursacht und bis zu 5-mal stapelbar ist.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[216625] = { ["name"] = "Rasanter Schlag", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure Nahkampfangriffe haben eine Chance von 100%, 4 bis 7 zusätzliche automatische Angriffe auszulösen. (10 Sek. Abklingzeit)\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[216626] = { ["name"] = "Töten", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Wenn Ihr einen Gegner angreift, der weniger als 10% Gesundheit besitzt, versucht Ihr, ihn zu 'Töten', was Schattenschaden in Höhe von 100% Eurer maximalen Gesundheit verursacht.\n\nIhr könnt höchstens einmal versuchen, einen Gegner zu 'Töten'.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[216627] = { ["name"] = "Schild des Tüftlermeisters", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Gewährt einen Schild, der Schaden in Höhe von 15% Eurer Gesamtgesundheit verursacht.\n\nDieser Schild regeneriert sich, wenn er 5 Sek. lang keinen Schaden erleidet.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[216628] = { ["name"] = "Siegesfeuer", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Immer, wenn Ihr einen Gegner besiegt, brecht Ihr aus, was innerhalb von 12 Metern Gegnern Feuerschaden zufügt und Verbündete heilt.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[216629] = { ["name"] = "Blinzeln", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nBlinzeln\nTeleportiert Euch 20 Meter, oder bis Ihr auf ein Hindernis stoßt, vorwärts und befreit Euch von Betäubungs- und Bewegungsunfähigkeitseffekten.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[216630] = { ["name"] = "Heldenhafter Sprung", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nHeldenhafter Sprung\nSpringt durch die Luft zu einem Zielort und schmettert mit zerstörerischer Gewalt auf den Boden, sodass alle Gegner innerhalb von 8 Metern (23.5% der Zaubermacht + 23.5% der Angriffskraft) körperlichen Schaden erleiden.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[216631] = { ["name"] = "Rollen", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nRollen\nRollt eine kurze Entfernung.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[216632] = { ["name"] = "Sprinten", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nSprinten\nErhöht Eure Bewegungsgeschwindigkeit 8 Sek. lang um 70%.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[216638] = { ["name"] = "Anfängerset des Zeitläufers", ["text"] = "Wird beim Aufheben gebunden\n80 ( 80)\n<Zum Öffnen rechtsklicken>" }
entries[216639] = { ["name"] = "Fehlerhafter Opal der Flinkheit", ["text"] = "Prismatischer Edelstein\nBenutzen: Kombiniert 3 dieser Edelsteine zu einem noch mächtigeren Edelstein.\n80 ( 80)\n\"Passt in einen prismatischen Sockel. Die gewährte Macht hängt vom eingesetzten Gegenstand ab.\"" }
entries[216640] = { ["name"] = "Fehlerhafter meisterhafter Amethyst", ["text"] = "Prismatischer Edelstein\nBenutzen: Kombiniert 3 dieser Edelsteine zu einem noch mächtigeren Edelstein.\n80 ( 80)\n\"Passt in einen prismatischen Sockel. Die gewährte Macht hängt vom eingesetzten Gegenstand ab.\"" }
entries[216641] = { ["name"] = "Fehlerhafter Rubin des Hungers", ["text"] = "Prismatischer Edelstein\nBenutzen: Kombiniert 3 dieser Edelsteine zu einem noch mächtigeren Edelstein.\n80 ( 80)\n\"Passt in einen prismatischen Sockel. Die gewährte Macht hängt vom eingesetzten Gegenstand ab.\"" }
entries[216642] = { ["name"] = "Fehlerhafter Smaragd der Erhaltung", ["text"] = "Prismatischer Edelstein\nBenutzen: Kombiniert 3 dieser Edelsteine zu einem noch mächtigeren Edelstein.\n80 ( 80)\n\"Passt in einen prismatischen Sockel. Die gewährte Macht hängt vom eingesetzten Gegenstand ab.\"" }
entries[216643] = { ["name"] = "Fehlerhafter Topas der Schnelligkeit", ["text"] = "Prismatischer Edelstein\nBenutzen: Kombiniert 3 dieser Edelsteine zu einem noch mächtigeren Edelstein.\n80 ( 80)\n\"Passt in einen prismatischen Sockel. Die gewährte Macht hängt vom eingesetzten Gegenstand ab.\"" }
entries[216644] = { ["name"] = "Fehlerhafter tödlicher Saphir", ["text"] = "Prismatischer Edelstein\nBenutzen: Kombiniert 3 dieser Edelsteine zu einem noch mächtigeren Edelstein.\n80 ( 80)\n\"Passt in einen prismatischen Sockel. Die gewährte Macht hängt vom eingesetzten Gegenstand ab.\"" }
entries[216647] = { ["name"] = "Hagelsturm", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Baut alle 3 Sek. eine Aufladung von 'Hagelsturm' auf. Bei 10 Stapeln wird Hagel auf Gegner innerhalb von 50 Metern entfesselt. Jeder Einschlag verursacht Frostschaden und belegt Gegner mit 'Betäubende Kälte'.\n\nBetäubende Kälte\nVerringert die Bewegungsgeschwindigkeit um 30% und den verursachten Schaden um 10%. Angreifen entfernt einen Stapel 'Betäubende Kälte'.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[216648] = { ["name"] = "Kaltfront", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure Fähigkeiten haben eine Chance, bis zu 5 Verbündeten einen Schild zu gewähren, der gleichmäßig aufgeteilt Schaden absorbiert, und alle Gegner innerhalb von 50 Metern mit 'Betäubende Kälte' zu belegen.\n\nBetäubende Kälte\nVerringert die Bewegungsgeschwindigkeit um 30% und den verursachten Schaden um 10%. Angreifen entfernt einen Stapel 'Betäubende Kälte'.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[216649] = { ["name"] = "Brüchig", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure Fähigkeiten belegen Gegner mit 'Brüchig', was 10% Eures verursachten Schadens ansammelt. Wenn ein mit 'Brüchig' belegter Gegner getötet wird, explodiert er und fügt Gegnern innerhalb von 12 Metern Frostschaden zu, der gleichmäßig unter den Zielen aufgeteilt wird.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[216650] = { ["name"] = "Erinnerung an Rache", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Alle 10 Sek. 1% Hauptwert pro 5% verlorener Gesundheit.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[216651] = { ["name"] = "Sengendes Licht", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: 10% Eurer Heilung werden als 'Sengendes Licht' auf Verbündeten gebündelt. Nach 3 Sek. wird 'Sengendes Licht' verbraucht, um einen Verbündeten zu heilen und allen Gegnern innerhalb von 12 Metern Heiligschaden zuzufügen.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[216653] = { ["name"] = "Säckchen des Zeitläufers", ["text"] = "Wird beim Aufheben gebunden\n36 Platz Tasche\n80 ( 80)" }
entries[216655] = { ["name"] = "Goblinhaftrakete", ["text"] = "Verbrauchbares\nBenutzen: Verschießt ein Sperrfeuer aus Raketen, die einen Kleber enthalten, in einer Linie vor dem Zaubernden.\n\nDie Bewegungsgeschwindigkeit von Gegnern wird im Kleber drastisch verringert.\nVerkaufspreis:" }
entries[216657] = { ["name"] = "Testgegenstand C", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Erhöht Eure Bewegungsgeschwindigkeit um 50%, aber fügt Euch alle 1 Sek. Schaden in Höhe von 4% Eurer maximalen Gesundheit zu. Bewegungseinschränkende Effekte können Euch nicht auf unter 100% Eurer normalen Bewegungsgeschwindigkeit verlangsamen. Hält bis Abbruch an.\nVerkaufspreis:" }
entries[216658] = { ["name"] = "Schattenwerfer der Sureki", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Neruber nutzen diese Emitter, um Befehle und Nachrichten ranghoher Anführer zu übertragen.\"" }
