entries[216663] = { ["name"] = "Vergessenssphäre", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nVergessenssphäre\nFormt eine Kugel aus reinster Leere, die den von Gegnern innerhalb von 15 Metern erlittenen Schaden 10 Sek. lang um 15% erhöht. Nach 4 Sek. explodiert die Kugel, verursacht Schattenschaden und betäubt getroffene Gegner für 1 Sek.\n80 ( 80)\n\"Passt in einen Metasockel.\"" }
entries[216664] = { ["name"] = "Fädlingköder", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Spinnlingpheromongranate auf den Boden, um Spinnlinge von Rak-Ush anzulocken. (6 Sek. Abklingzeit)\n\"Ein granatenartiges Objekt, das Fädlinge von Rak-Ush anlockt.\"" }
