entries[216667] = { ["name"] = "Wappenrock des drakonischen Gladiators", ["text"] = "Saison 4 von Dragonflight\nWird beim Aufheben gebunden\nWappenrock\nErlangt den Rang Elite in Saison 4 von Dragonflight.\nVerkaufspreis:" }
entries[216668] = { ["name"] = "Prestigeträchtiger Umhang des drakonischen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nRücken\n9 Rüstung\n+9 [Beweglichkeit oder Stärke oder Intelligenz]\n+13 Ausdauer\nErhöht Eure Tempowertung um + 9.\nErhöht Eure Meisterschaftswertung um + 9.\nVerkaufspreis:" }
entries[216669] = { ["name"] = "Zerschmetterte Überbleibsel", ["text"] = "Questgegenstand\n\"Einst Teil einer machtvollen Schlüsselflamme.\"" }
entries[216670] = { ["name"] = "Feuerbienenwachs", ["text"] = "Questgegenstand\n\"Das weiche Wachs ist noch warm. Im Inneren befinden sich schimmernde Funken.\"" }
entries[216671] = { ["name"] = "Donnernde Kugel", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nDonnernde Kugel\nVerwandelt Euch in eine donnernde Kugel und fügt Gegnern innerhalb von 30 Metern im Verlauf von 4 Sek. Naturschaden zu. Als donnernde Kugel wird Euer erlittener Schaden um 50% und Eure Bewegungsgeschwindigkeit um 70% verringert. Außerdem werdet Ihr immun gegen Kontrollverlusteffekte.\n80 ( 80)\n\"Passt in einen Metasockel.\"" }
entries[216672] = { ["name"] = "Der Strauchdieb", ["text"] = "Verbrauchbares\nBenutzen: Verkleidet Euch als einfacher Strauch. Ihr und Eure Verbündeten seid unsichtbar, während Ihr verkleidet seid.\n\nEure Basiscombo wird durch 'Buschschlag' ersetzt, was Euer aktuelles Ziel betäubt.\nVerkaufspreis:" }
entries[216677] = { ["name"] = "Korgrans Laterne", ["text"] = "Questgegenstand\n73 ( 73)\n\"Der geladene Kern der Laterne taucht den Bereich in kaltes, blaues Licht. Auf der Unterseite befindet sich eine Gravur mit der Inschrift: \"Von Korgran und einem geschätzten Freund hergestellt\".\"" }
entries[216681] = { ["name"] = "Händlerstandteile", ["text"] = "Questgegenstand\n\"Ein abwechslungsreiches Bündel aus Holzverschnitten, rostigem Metall, Stofffetzen und verschiedenen Behältern, das nach Jankys Vorgaben zusammengestellt wurde.\"" }
entries[216682] = { ["name"] = "Die Einladung des Wesirs", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Einladung für ein Treffen mit dem Vertreter des Wesirs. Verdächtig persönlich.\"\n<Zum Lesen rechtsklicken>" }
