entries[216687] = { ["name"] = "Zusammengeflickte Verbände", ["text"] = "Questgegenstand\nBenutzen: Kann in der Not zur Heilung eines verletzten Soldaten verwendet werden. (2 Sek. Abklingzeit)\n\"Diese Verbände sehen aus, als hätte jemand einfach nur ein paar Stofffetzen zusammengeworfen. Sie werden die Heilung unterstützen, aber auch wirklich nur gerade so eben.\"" }
entries[216688] = { ["name"] = "Schlüssel zu den Hochhöhlen", ["text"] = "Questgegenstand\nEinzigartig\n\"Ag'thax in den Hochhöhlen wird sich sehr freuen, dass er jetzt in seinen neuen Bau kommt.\"" }
entries[216689] = { ["name"] = "Alberts Kopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Von Albert ist nur noch sein augenloser Kopf übrig.\"" }
entries[216693] = { ["name"] = "Schattenflutkrabbe", ["text"] = "Questgegenstand\n\"Sehr lebendig, sehr schnappfreudig. Gut, dass Ihr einen Käfig habt!\"" }
entries[216694] = { ["name"] = "Empfehlungsschreiben", ["text"] = "Questgegenstand\n\"Ohne Zweifel Eure beste Arbeit.\"" }
entries[216695] = { ["name"] = "Lebenssturm", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nLebenssturm\nBeschwört einen Sturm. Ruft alle 1 Sek. 5 Blitzschläge herab. Jeder Blitzschlag fügt einem Gegner innerhalb von 30 Metern Naturschaden zu.\n\nWährend des Sturms wachsen um den Zaubernden 3 Blumen. Nach 3 Sek. erblühen die Blumen und stellen bei Verbündeten Gesundheit wieder her und gewähren ihnen Tempo. Hält 10 Sek. lang an.\n80 ( 80)\n\"Passt in einen Metasockel.\"" }
entries[216696] = { ["name"] = "Versteckte Hosen", ["text"] = "Kosmetisch\nBeine Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[216697] = { ["name"] = "Signet des Ratsvorstehers", ["text"] = "Questgegenstand\n\"Der quadratische Stein dieses schweren Rings wurde im Laufe der Zeit durch Abnutzung geglättet. In das Band sind fremdartige Zeichen graviert.\"" }
entries[216708] = { ["name"] = "Heilige Kerze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Dekoriert einen Bereich mit einer Arathikerze, die 15 Min. lang brennt.\n\"Den Gefallenen zur Ehre und den Verlorenen ein Wegweiser.\"\nVerkaufspreis:" }
entries[216710] = { ["name"] = "Hochlanddrache: Verkörperung des drakonischen Gladiators", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den Hochlanddrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[216711] = { ["name"] = "Chi-Ji, der Rote Kranich", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt den folgenden Zauber.\n\nChi-Ji, der Rote Kranich\nErhöht die Bewegungsgeschwindigkeit um 50%, gewährt Immunität gegen bewegungseinschränkende Effekte und folgende Zauber. Hält 20 Sek. lang an.\n\nKranichschwarm\nFlattert ein kurzes Stück vorwärts.\n\nFlammende Nova\nEine Feuerexplosion wirft Euch zurück, was Gegnern innerhalb von 10 Metern Feuerschaden zufügt und Verbündete in diesem Bereich heilt.\n\nGefieder der Hoffnung\nChi-Ji wirft alle 2 Sek. eine Feder ab. Wer die Feder berührt, löst eine Salve von 'Flamme der Hoffnung' aus, die Gegnern Schaden zufügt und Verbündete heilt.\n\nFlamme der Hoffnung\nFügt Gegnern innerhalb von 30 Metern alle 2 Sek. Feuerschaden zu oder stellt bei Verbündeten in diesem Bereich Gesundheit wieder her. Betrifft 5 Ziele.\n80 ( 80)\n\"Passt in einen Metasockel.\"" }
entries[216712] = { ["name"] = "Bronzene Taschenuhr", ["text"] = "Questgegenstand\nEinzigartig\n80 ( 80)\n\"Wenn Ihr dies benutzt, wird die Zeit zurückgedreht und Eure Position zurückgesetzt.\"" }
entries[216719] = { ["name"] = "Kapitän Fasshaxes Kanonade", ["text"] = "Verbrauchbares\nBenutzen: Signalisiert Fasshaxe, dass er Eure Position mit einem Kanonensperrfeuer belegen soll. Das Sperrfeuer fügt ALLEN Zielen, die von ihm erfasst werden, schweren Schaden zu.\nVerkaufspreis:" }
entries[216720] = { ["name"] = "Wertvolle Teile", ["text"] = "Questgegenstand\n\"Eine fettverschmierte Anhäufung esoterischer Maschinenteile.\"" }
entries[216722] = { ["name"] = "Rauchbombe", ["text"] = "Verbrauchbares\nBenutzen: Lässt eine Rauchbombe an Eurer Position fallen, die Euch und Euren Verbündeten für kurze Zeit Verstohlenheit gewährt.\nVerkaufspreis:" }
entries[216723] = { ["name"] = "Hühnerparade", ["text"] = "Verbrauchbares\nBenutzen: Wirft eine Kiste mit wütenden Hühnern. Die Hühner toben sich aus und greifen ALLE Einheiten in der Nähe an.\nVerkaufspreis:" }
