entries[216851] = { ["name"] = "Angriffsleuchtfeuer der Furchtloser Funke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Signalisiert Kapitänin Lancekat des Luftschiffs Furchtloser Funke, den Angriff auf die Verblasste Küste zu beginnen.\nBenötigt Ruhmrang 12 bei den Arathi von Heilsturz.\n\"Es bedarf einer Menge Überreste, um dieses Leuchtfeuer auch noch Kilometer entfernt sehen zu können.\"\nVerkaufspreis:" }
entries[216858] = { ["name"] = "Freydrins Shillelagh", ["text"] = "Questgegenstand\n73 ( 73)\n\"Eine jenseitige Lebensenergie schwingt durch den Wald.\"" }
entries[216874] = { ["name"] = "Beutegefüllter Korb", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Nobelgartenfest\n<Zum Öffnen rechtsklicken>" }
entries[216878] = { ["name"] = "Manipulierte Truhe", ["text"] = "Verbrauchbares\nBenutzen: Platziert eine manipulierte Truhe mit einer Bombe darin. Die Zeit bis zur Explosion der Bombe beginnt, sobald die Truhe geöffnet wird. Die Bombe fügt allen Zielen in der Nähe, die von der Explosion erfasst werden, Schaden zu.\nVerkaufspreis:" }
entries[216881] = { ["name"] = "Entenverkleidungsspielzeug", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört ein Ei, mit dem Ihr Euch in eine winzige Ente verwandeln könnt. (3 Min Abklingzeit)" }
entries[216882] = { ["name"] = "Eintrag 467-21-5", ["text"] = "Questgegenstand\n\"Beobachtung: Die Myzelausbreitung hat alarmierende Ausmaße angenommen und greift nun auf benachbarte Vegetation über. Die Fungianer zeigen eine gesteigerte Reaktion auf umweltbedingte Stimuli, was auf einen potenziellen Wandel in ihrem ökologischen Verhalten deuten könnte.\"\n<Zum Lesen rechtsklicken>" }
entries[216888] = { ["name"] = "Eintrag: 652-12-3", ["text"] = "Questgegenstand\n\"Anmerkung: Fungianer zeigen aggressive mykorrhizalische Interaktionen, die andere konkurrierende Fungusarten verdrängen. Das beschleunigte Wachstum wirft Bedenken hinsichtlich der potenziellen ökologischen Ungleichgewichte im betroffenen Bereich auf.\"\n<Zum Lesen rechtsklicken>" }
entries[216889] = { ["name"] = "Eintrag: 893-03-9", ["text"] = "Questgegenstand\n\"Beobachtung: Fungianer breiten sich nun über den ursprünglichen Studienbereich hinweg aus. Es wurden aggressive Myzelübergriffe in unerwarteten Habitaten festgestellt. Es bedarf einer dringenden Untersuchung, um die ökologischen Auswirkungen dieses neuartigen Verhaltens festzustellen (...)\"\n<Zum Lesen rechtsklicken>" }
