entries[217010] = { ["name"] = "Zerbrochenes Medaillon der Draenei", ["text"] = "Einzigartig\n\"Eine Auszeichnung für jene, die den Eredar von Argus, den jetzigen Draenei von Azeroth, geholfen haben. Die Auszeichnung kann über jeden Händler zur Exodar zurückgeschickt werden, ohne jemanden zu beleidigen.\"\nVerkaufspreis:" }
