entries[217016] = { ["name"] = "Zerbrochenes Medaillon der Dunkelspeere", ["text"] = "Einzigartig\n\"Eine Auszeichnung für jene, die den Loa und Trollen des Dunkelspeerstamms geholfen haben. Die Auszeichnung kann über jeden Händler nach Sen'jin zurückgeschickt werden, ohne den Zorn der Loa heraufzubeschwören.\"\nVerkaufspreis:" }
