entries[217159] = { ["name"] = "Nebbs verbesserter Wickel", ["text"] = "Questgegenstand\n\"Erfüllt mit dem königlichen Gift der Kriecherkönigin.\"" }
entries[217162] = { ["name"] = "Halskette aus Koboldzähnen", ["text"] = "\"Klein, scharf und vermutlich gestohlen.\"\nVerkaufspreis:" }
entries[217163] = { ["name"] = "Stark verschlissene Puppe", ["text"] = "\"\"Mr. Knuddeldocht\" wurde mit unsteter Hand auf die Rückseite der Puppe geschrieben.\"\nVerkaufspreis:" }
entries[217164] = { ["name"] = "Königlicher Nageltrimmer", ["text"] = "\"Eine erbeutete Klinge der Irdenen, die zu sehr verrostet und verbeult ist, um noch von Nutzen zu sein. Mit Dingen verkrustet, über die man besser nicht nachdenken sollte.\"\nVerkaufspreis:" }
entries[217165] = { ["name"] = "Zev'kalls Zermürbungsprotokoll", ["text"] = "Questgegenstand\n\"Eine detaillierte Beschreibung der Verluste der nerubischen Truppen an der Belagerungsfeste.\"" }
entries[217167] = { ["name"] = "Krustiger Kelch", ["text"] = "\"Ein alter Stiefel, der Flecken von Wein und anderen, düstereren Dingen aufweist.\"\nVerkaufspreis:" }
entries[217168] = { ["name"] = "Schokoladenmünzen", ["text"] = "\"Von einigen der Münzen wurde ein Stück abgebissen. Vorher ausgepackt wurde allerdings keine.\"\nVerkaufspreis:" }
entries[217169] = { ["name"] = "Mantel der Bärte", ["text"] = "\"Krude gewoben aus den abrasierten, drahtigen Bärten gefallener Irdener.\"\nVerkaufspreis:" }
entries[217170] = { ["name"] = "Reservekerzen", ["text"] = "\"Man kann nie genug haben! - Krabbler\"\nVerkaufspreis:" }
entries[217171] = { ["name"] = "TAGEBUCH DES KERZENKÖNIGS", ["text"] = "\"Dickes Buch. Schweres Buch. Viele Wörter.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[217174] = { ["name"] = "Bronze", ["text"] = "Questgegenstand\n80 ( 80)\n\"Die Ewigen als Verbündete von Eternus handeln mit losen Zeitfäden, die sie in Bronzemünzen pressen.\"" }
entries[217175] = { ["name"] = "Scharfschuppenkopf", ["text"] = "Questgegenstand\nEinzigartig\n\"Trieft vor Blut und Wasser. Man kann den fauligen Gestank sogar durch die Tasche riechen.\"" }
entries[217176] = { ["name"] = "Halsberge der Erweckten", ["text"] = "Wird beim Aufheben gebunden\nBrust Kette\n1928 Rüstung\n+862 [Beweglichkeit oder Intelligenz]\n+3.652 Ausdauer\nErhöht Eure Tempowertung um + 294.\nErhöht Eure Meisterschaftswertung um + 734.\nHaltbarkeit 165 / 165\nKlassen: Rufer\nSchuppen der Erweckten (0/5)\nHalsberge der Erweckten\nStulpen der Erweckten\nKrone der Erweckten\nBeinschützer der Erweckten\nKrallen der Erweckten\n(2) Set Verheerung: 'Desintegration' und 'Scheiterhaufen' durchbohren Gegner mit Obsidiansplittern, die 18% des Schadens als Vulkanschaden über 8 Sek. verursachen.\n(2) Set Bewahrung: 'Geisterblüte' wendet einen regelmäßigen Heileffekt von 40% der hervorgerufenen Heilung über 8 Sek. an. 'Traumatem' ruft 15% mehr Heilung hervor.\n(2) Set Verstärkung: Jeder dritte Einsatz von dritte 'Voraussicht' hält 100% länger an.\n(4) Set Verheerung: Ermächtigungszauber verursachen 12% mehr Schaden und lassen Eure Obsidiansplitter mit Macht lodern, wodurch diese 5 Sek. lang 200% mehr Schaden verursachen. Während 'Drachenwut' lodern Eure Splitter immer mit Macht.\n(4) Set Bewahrung: Nachdem Ihr 4 Ermächtigungszauber gewirkt habt, erhaltet Ihr eine 'Essenzexplosion' sofort und eine weitere 3 Sek. später.\n(4) Set Verstärkung: Das Wirken von 'Voraussicht' verbessert Eure nächste 'Eruption' mit schmaleren Rissen für jede aktive 'Voraussicht', die jeweils (110% der Zaubermacht) Schaden verursachen und 'Schwarzmacht' um 0.2 Sek verlängern.\nVerkaufspreis:" }
