entries[217241] = { ["name"] = "Truhe mit erweckter Ausrüstung", ["text"] = "Saison 4 von Dragonflight\nWird an Kriegsmeute gebunden\nBenutzen: Erschafft einen seelengebundenen Gegenstand eines Dungeons des Schwierigkeitsgrads Mythisch+, der in Saison 4 von Dragonflight für Eure Beutespezialisierung nützlich ist.\nErfordert eine Wertung für Mythisch+ von: 1.000." }
entries[217242] = { ["name"] = "Erwachende Steinschwinge", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stimmt Euch auf den Stein ein, um Flugsteine und vielleicht sogar einige erweckte Wappen des Welpen zu entdecken." }
