entries[217340] = { ["name"] = "Geschirr des reisenden Wildlings", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen reisenden Wildling beschwört.\nBeschwört einen reitbaren reisenden Wildling oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese verspielten Besucher aus einer anderen Welt fühlen sich wohl, wenn sie mit neuen Freunden neue Länder bereisen.\"\nErfolg:\nErweckt die Schlachtzüge von Dragonflight" }
entries[217342] = { ["name"] = "Trunk der Furchtloser Funke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Erhöht die kritische Trefferchance 30 Min. lang um 10%. Nur einsetzbar bei Abenteuern in Heilsturz.\n\"Beliebt bei Kapitänin Lancekat und der Besatzung der Furchtloser Funke.\"" }
entries[217343] = { ["name"] = "Lebendiger geronnener Schlick", ["text"] = "Questgegenstand\n\"Urzeitliche Energie fließt durch den elementaren Schlick.\"" }
entries[217344] = { ["name"] = "Abschussgerät für Wachpostenleuchtfeuer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Rüstet das Abschussgerät für Wachpostenleuchtfeuer aus, mit dem auf ein Gebiet geschossen werden kann, um verborgene Gegenstände aufzudecken und Gegnern in der Nähe Schaden zuzufügen.\n\nKann in der Fackelscheinmine und angrenzenden Schlüsselflammengebieten eingesetzt werden." }
entries[217348] = { ["name"] = "Arkane Überreste", ["text"] = "Questgegenstand\n\"Obwohl dieses schillernde Pulver nicht sehr konzentriert ist, enthält es dennoch die explosive Macht der Magie selbst.\"" }
entries[217352] = { ["name"] = "Keuchender Fisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenutzen: Lasst den Fisch ins Wasser fallen.\n78 ( 78)\n\"Seine ausgetrockneten Lippen bewegen sich schwach, als ob er flüstern würde.\"" }
