entries[217386] = { ["name"] = "Weggeworfener Erinnerungsedelstein", ["text"] = "Wird beim Aufheben gebunden\n\"Die Neruber konnten nichts Wertvolles an diesem Edelstein entdecken.\"" }
entries[217387] = { ["name"] = "Prinzessinnenkürbis", ["text"] = "80 ( 80)\n\"Dieser Kürbis trägt eine winzige Krone, die seine preisgekrönte Gestalt betont.\"" }
entries[217388] = { ["name"] = "Kiste mit Andachtskerzen", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Janky, der Koboldkerzenschmied in Gundargaz, könnte daran interessiert sein.\"" }
entries[217389] = { ["name"] = "Andachtskerze", ["text"] = "Questgegenstand\n\"Ein Kobold würde sie als gut gealtert und durchaus nützlich betrachten.\"" }
entries[217390] = { ["name"] = "Geronnener Schwarzblutklumpen", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Janky, der Koboldkerzenschmied in Gundargaz, könnte daran interessiert sein.\"" }
entries[217391] = { ["name"] = "Geronnenes Schwarzblut", ["text"] = "Questgegenstand\n\"Die verwesten, zersetzten Überreste vergessener Schrecken. Grässlich in Form und Macht. Was für eine Kerze sich daraus wohl machen lässt?\"" }
entries[217395] = { ["name"] = "Frisch geschmiedete Werkzeuge", ["text"] = "Questgegenstand\n\"Vorarbeiterin Shaelas bestellte Ersatzwerkzeuge. Sie qualmen noch von der Hitze der Schmiede.\"" }
entries[217396] = { ["name"] = "Ei vom Hügelpinnenhof", ["text"] = "Questgegenstand" }
entries[217397] = { ["name"] = "Münze mit Fassstempel", ["text"] = "Wird an Kriegsmeute gebunden\n\"Eine Münze mit einem unpräzisen Bild eines Fasses darauf. Da'kash Grimjoch im Gerösteten Geißbock in Valdrakken würde sich dafür interessieren.\"" }
entries[217400] = { ["name"] = "Kobyssköder", ["text"] = "Questgegenstand\nBenutzen: Wehrt Ungeziefer mit einem Schwung Eurer brennenden Fackel ab." }
entries[217401] = { ["name"] = "Resonator des Wurmrufers", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört einen zweiköpfigen Höhlenbohrer, der Euren aktuellen Standort und Euren Zielort verbindet. Ihr könnt Euch auf einer Seite in den Höhlenbohrer begeben, um auf der anderen Seite herauszukommen." }
entries[217402] = { ["name"] = "Altertümliche Rüstungsverzauberung", ["text"] = "Wird beim Aufheben gebunden\nSchmuck" }
entries[217403] = { ["name"] = "Altertümliche Waffenverzauberung", ["text"] = "Wird beim Aufheben gebunden\nSchmuck" }
entries[217404] = { ["name"] = "Von der Zeit gezeichnete Rüstungsverzauberung", ["text"] = "Wird beim Aufheben gebunden\nSchmuck" }
entries[217405] = { ["name"] = "Von der Zeit gezeichnete Waffenverzauberung", ["text"] = "Wird beim Aufheben gebunden\nSchmuck" }
entries[217408] = { ["name"] = "Erweckter Tempostein", ["text"] = "Wird beim Aufheben gebunden\n\"Zerrissene Memoiren, die sich mit dem Erwachen der Inseln beschäftigen. Runaagos im \"Zum Letzten Glas\" in Valdrakken könnte vielleicht wissen, wie man die Geheimnisse, die darin liegen, offenbart.\"" }
entries[217409] = { ["name"] = "Aspektzeichen der Belobigung", ["text"] = "Saison 4 von Dragonflight\nWird beim Aufheben gebunden\nEinzigartig (12)\nVerkaufspreis:" }
entries[217410] = { ["name"] = "Erwecktes Mal der Meisterschaft", ["text"] = "Saison 4 von Dragonflight\nWird beim Aufheben gebunden\nEinzigartig\n\"Verliehen für herausragende Taten für die Drachenheit. Bringt es zu Harrostrasza im \"Zum Letzten Glas\" in Valdrakken, um für Eure Hilfe mächtige Ausrüstung zu erhalten.\"" }
