entries[217414] = { ["name"] = "Passrune der Spelunke", ["text"] = "Questgegenstand\n\"Die Rune ist der Form eines Zahnrads nachempfunden und weist viele scharfe Kanten und Details auf. Nur ein begabter Maschinenflüsterer könnte das aus dem Gedächtnis herstellen.\"" }
