entries[217494] = { ["name"] = "Glyphe 'Faelinienstampfen'", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Mönch\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eurer Fähigkeit 'Jadefeuerstampfen' hat nun die Farbe der Paktfähigkeit der Nachtfae.\nBenötigt Die Wilde Jagd\n- Wohlwollend\nVerkaufspreis:" }
entries[217498] = { ["name"] = "Beschlagnahmte Lieferung", ["text"] = "Questgegenstand\n\"Nichts Ungewöhnliches.\"" }
entries[217499] = { ["name"] = "Ausgewählte Meißel", ["text"] = "Questgegenstand\n\"Verschiedene Formen und Größen, die auf eine Vielzahl verschiedener Steinarten spezialisiert sind.\"" }
entries[217500] = { ["name"] = "Hochwertige Kohle", ["text"] = "Questgegenstand\n\"Robuste Briketts, die mehrere Stunden lang brennen können.\"" }
entries[217501] = { ["name"] = "Schürze aus Maulwurfhaut", ["text"] = "Questgegenstand\n\"Verhindert Verbrennungen und von Spritzern von geschmolzenem Metall getroffen zu werden.\"" }
entries[217502] = { ["name"] = "Energieerfüllter Unterton", ["text"] = "Questgegenstand\n\"Dieser Ton wurde mit heiligem Öl aus Heilsturz erfüllt und kann wochenlang brennen.\"" }
entries[217503] = { ["name"] = "Nerubische Seidenseile", ["text"] = "Questgegenstand\n\"Diese elastischen Seile sind aus nerubischen Netzen gewebt und reißen nicht.\"" }
entries[217504] = { ["name"] = "Belegbündel", ["text"] = "Questgegenstand\n\"Jeder einzelne Beleg wurde von derselben Person unterzeichnet: \"Stahlader\".\"" }
entries[217505] = { ["name"] = "Tasche mit leuchtenden Splittern", ["text"] = "Questgegenstand\n\"Diese kleinen Splitter brechen leicht und geben dabei einen belebenden Funken Elektrizität frei.\"" }
