entries[217605] = { ["name"] = "Zeitlose Schriftrolle der Intelligenz", ["text"] = "Benutzen: Erfüllt das Ziel mit Brillanz, die seine Intelligenz 1 Stunde lang um 4% erhöht.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, erhalten alle Mitglieder den Effekt.\n80 ( 80)" }
entries[217606] = { ["name"] = "Zeitlose Schriftrolle der Seelenstärke", ["text"] = "Benutzen: Erfüllt das Ziel mit Lebenskraft, die seine Ausdauer 1 Stunde lang um 4% erhöht.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, erhalten alle Mitglieder den Effekt.\n80 ( 80)" }
entries[217607] = { ["name"] = "Zeitlose Schriftrolle der Wildnis", ["text"] = "Benutzen: Erfüllt ein verbündetes Ziel mit der Macht der Wildnis. Erhöht die Vielseitigkeit des Ziels 1 Stunde lang um 2%.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, erhalten alle Mitglieder den Effekt.\n80 ( 80)" }
entries[217608] = { ["name"] = "Zeitlose Schriftrolle des Schlachtrufs", ["text"] = "Benutzen: Erhöht die Angriffskraft aller Gruppen- und Schlachtzugsmitglieder innerhalb von 100 Metern 1 Stunde lang um 4%.\n80 ( 80)" }
entries[217610] = { ["name"] = "Erinnerungsedelstein eines Irdenen", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser eckig geschliffene Edelstein ist schwer für seine Größe und leuchtet schwach. Die Irdenen haben diesen Speicher in Edelsteinform zur Programmierung ihrer Erinnerungen entwickelt. Er kann auf die Archive der Irdenen hochgeladen werden.\"" }
entries[217612] = { ["name"] = "Halsband von Zovaals Schemenbestie", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"War ich ein guter Junge?\", fragte die Seele Zovaal. \"Nein. Ich habe gehört, Ihr wart der Schlimmste.\"\nErfolg:\nZurück aus dem Jenseits\nKategorie:\nErweiterungsfeatures" }
entries[217614] = { ["name"] = "Arathirationen", ["text"] = "Questgegenstand\n\"Ein einfacher Eintopf aus herzhaften Zutaten. Macht satt, ist tröstlich, aber es fehlt Salz.\"" }
