entries[217705] = { ["name"] = "Piratenbeute", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\n\"Es gibt nur eine (pro Battle.net Account) und sie riecht komisch, aber sie enthält immer noch ein Ausrüstungsteil von Saison 3 aus Amirdrassil, Hoffnung des Traums, auf dem Schwierigkeitsgrad 'Normal'.\"\n<Zum Öffnen rechtsklicken>" }
entries[217707] = { ["name"] = "Mangelhafter Nullstein", ["text"] = "Benutzen: Kombiniert 5 Exemplare dieses Gegenstands, um einen makellosen Nullstein zu schmieden.\nHandwerksmaterial\n\"Wird manchmal von Spielercharakteren gesammelt, die den Beruf Bergbau ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[217708] = { ["name"] = "Eine Runde Getränke", ["text"] = "Questgegenstand\n\"Ihr seid Euch nicht sicher, welche Getränke die Arathi so haben, aber Ihr könntet schwören, ein Stück Pilz an die Oberfläche steigen gesehen zu haben.\"\nVerkaufspreis:" }
