entries[217730] = { ["name"] = "Zeitlose Schriftrolle des Chaos", ["text"] = "Benutzen: Euer Schaden fügt dem Ziel ein Brandmal zu, das dessen erlittenen Magieschaden 1 Stunde lang um 2% erhöht.\n80 ( 80)" }
