entries[217735] = { ["name"] = "Gebet der geläuterten Gewalt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDer nächste Angriff, der Eure Gesundheit unter 35% bringt, löst ' Geläuterte Gewalt ' aus.\n\nGeläuterte Gewalt :\nSchützt den Zaubernden 8 Sek. lang vor sämtlichen Angriffen und Zaubern.\n80 ( 80)" }
