entries[217894] = { ["name"] = "Neruberpheromonabsonderer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nDuftsockel\nDuftsockel\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, verschiedene Pheromone um Euch abzusondern. Wenn Ihr diese Pheromone berührt, wird Euer Primärwert 20 Sek. lang um 2051 erhöht. (20s Abklingzeit)\nVerkaufspreis:" }
entries[217895] = { ["name"] = "Flüchtiges Pheromon", ["text"] = "\"Eine seltsame Chemikalie schwimmt in der Flasche. Sie hat bestimmt keine langfristigen Nebenwirkungen... oder?\"" }
entries[217896] = { ["name"] = "Glutbräumet", ["text"] = "Benutzen: Ein ziemlich schwaches alkoholisches Getränk.\n\"Randvoll mit blubberndem, dampfendem Met.\"\nVerkaufspreis:" }
entries[217897] = { ["name"] = "Flüchtiges Pheromon", ["text"] = "\"Dieser Behälter vibriert aufgrund der seltsamen Substanz in seinem Inneren.\"" }
entries[217898] = { ["name"] = "Gebet des geläuterten Hasses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDer nächste Angriff, der Eure Gesundheit unter 35% bringt, löst ' Geläuterter Hass ' aus.\n\nGeläuterter Hass :\nStellt Eure Gesundheit, Euren Elan und Eure Klassenressourcen vollständig wieder her.\n80 ( 80)" }
entries[217899] = { ["name"] = "Gebet des geläuterten Stolzes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nErlangt außerhalb des Kampfes ' Geläuterter Stolz '.\n\nGeläuterter Stolz :\nVerschwindet von der Bildfläche in die Verstohlenheit. Euer nächster Angriff erzielt garantiert einen kritischen Treffer.\n80 ( 80)" }
entries[217900] = { ["name"] = "Gebet des geläuterten Zorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWenn Ihr das nächste Mal getroffen werdet, entfesselt Ihr ' Geläuterter Zorn '.\n\nGeläuterter Zorn :\nFügt Gegnern innerhalb von 8 Metern 2625000 körperlichen Schaden zu und betäubt sie für 3 Sek.\n80 ( 80)" }
entries[217901] = { ["name"] = "Zeitlose Trommeln", ["text"] = "Benutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder ähnlichen Effekten profitieren. (2 Min Abklingzeit)\n80 ( 80)" }
entries[217902] = { ["name"] = "Phiole des Zeitläufers", ["text"] = "Benutzen: Erhöht Eure Manaregeneration 6 Sek. lang um 1000%.\n\nVerringert die Bewegungsgeschwindigkeit um 50%. (6 Sek. Abklingzeit)\n80 ( 80)" }
entries[217903] = { ["name"] = "Rechtschaffene Stärkung", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: 10% Eures Schadens wird als 'Rechtschaffene Stärkung' gesammelt. 'Rechtschaffene Stärkung' wird alle 3 Sek. verbraucht und heilt bis zu 3 Verbündete innerhalb von 50 Metern um die verbrauchte Menge.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[217904] = { ["name"] = "Zeitläufertrunk der Macht", ["text"] = "Benutzen: Stellt 525000 Mana wieder her und erhöht Hauptwert 30 Min. lang um 3%. (5 Min Abklingzeit)\n80 ( 80)\n\"Zusätzliche Vorräte sind bei Nostwin an beliebigen Ewigen Basaren erhältlich.\"" }
entries[217905] = { ["name"] = "Zeitläufertrunk der Gesundheit", ["text"] = "Benutzen: Stellt 1050000 Gesundheit wieder her und erhöht die Ausdauer 30 Min. lang um 3%. (5 Min Abklingzeit)\n80 ( 80)\n\"Zusätzliche Vorräte sind bei Nostwin an beliebigen Ewigen Basaren erhältlich.\"" }
entries[217906] = { ["name"] = "Drachenleckerli", ["text"] = "Einzigartig (3)\nBenutzen: Stellt Aufladungen für Himmelsreiten vollständig wieder her und gewährt der Fluggeschwindigkeit einen Schub. Nur beim Himmelsreiten einsetzbar. (15 Sek. Abklingzeit)\n80 ( 80)" }
entries[217907] = { ["name"] = "Wärme", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erhöht die erhaltene Heilung um 10%. 75% der überschüssigen Heilung wird als 'Wärme' gesammelt. 'Wärme' wird alle 5 Sek. verbraucht und heilt einen verletzten Verbündeten innerhalb von 50 Metern um die verbrauchte Menge.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[217925] = { ["name"] = "Flasche voller Bienen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)\nBenutzen: Ärgert alle Gegner innerhalb von 40 Metern um den Zielort, fordert sie zum Kampf heraus und belegt sie 30 Sek. lang mit 'Beulen'. Nur im Freien einsetzbar.\n\nBeulen :\nLässt einen Gegner 30 Sek. lang 5% mehr Schaden erleiden. Wenn der Gegner Schaden erleidet, besteht die Chance, dass ihm weitere Beulen zugefügt werden. (1 Min Abklingzeit)\n80 ( 80)\n\"Sie summen wie wild.\"" }
entries[217926] = { ["name"] = "Flasche voller toter Bienen", ["text"] = "Benutzen: Fügt Gegnern im Umkreis von 3 Metern 26250 körperlichen Schaden zu. (1 Min Abklingzeit)\n80 ( 80)\n\"Uups.\"" }
entries[217927] = { ["name"] = "Retter", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Wenn ein Verbündeter mit weniger als 35% Gesundheit geheilt wird, erhält er einen Absorptionsschild in Höhe von 50% der hervorgerufenen Heilung.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[217928] = { ["name"] = "Zeitlose Schriftrolle der Auferstehung", ["text"] = "Benutzen: Bringt einen toten Verbündeten mit 35% Gesundheit und Mana ins Leben zurück. Kann nicht während des Kampfes verwendet werden. (30 Sek. Abklingzeit)\n80 ( 80)" }
entries[217929] = { ["name"] = "Zeitlose Schriftrolle der Läuterung", ["text"] = "Benutzen: Hebt alle Flüche, Krankheiten, Gifte und schädlichen magischen Effekte des anvisierten Verbündeten auf. (30 Sek. Abklingzeit)\n80 ( 80)\n\"Die Zeit heilt alle Wunden, Krankheiten, Flüche, Kater...\"" }
entries[217930] = { ["name"] = "Nostwins Gutschein", ["text"] = "Benutzen: Bringt Euch zu einem Ewigen Basar in der Nähe zurück. (15 Min Abklingzeit)\n80 ( 80)\n\"Beehrt uns bald wieder!\"" }
entries[217956] = { ["name"] = "Zeitlose Schriftrolle der Beschwörung", ["text"] = "Benutzen: Führt ein Ritual zur Erschaffung eines Beschwörungsportals durch, das 3 Min. lang bestehen bleibt und von Verbündeten benutzt werden kann, um ein ausgewähltes Gruppen- oder Schlachtzugsmitglied zu beschwören. (30 Sek. Abklingzeit)\n80 ( 80)" }
entries[217957] = { ["name"] = "Rettung", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: 4% der Heilung wird als Errettung angesammelt. Liegt die Gesundheit eines Verbündeten nach von Euch erhaltener Heilung unter 50%, wird die Errettung verbraucht und heilt bis zu 3 Verbündete innerhalb von 50 Metern um die verbrauchte Menge. Die Heilung wird gleichmäßig unter ihnen aufgeteilt.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[217958] = { ["name"] = "Gebrauchte Socken", ["text"] = "\"Unglücklicherweise waren in diesen Truhen nicht nur Schätze.\"\nVerkaufspreis:" }
entries[217959] = { ["name"] = "Unvollständiges Gemälde", ["text"] = "\"Ein Gemälde, das vage ein Leben in Reichtum darstellt, es fehlen jedoch viele der Details.\"\nVerkaufspreis:" }
entries[217960] = { ["name"] = "Vergessener Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wer würde einen Schlüssel für eine Kiste in einer Kiste aufbewahren?\"" }
entries[217961] = { ["name"] = "Rechtschaffene Raserei", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Wenn ein Verbündeter geheilt wird, ereilt ihn eine 'Rechtschaffene Raserei', die jede Sekunde 2% Gesundheit verbraucht und 5 Sek. lang 7% mehr Tempo gewährt.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[217962] = { ["name"] = "Blindgängerbombe", ["text"] = "\"Zum Glück scheint es inaktiv zu sein.\"\nVerkaufspreis:" }
entries[217964] = { ["name"] = "Heiliger Märtyrer", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: 5% des erlittenen Schadens wird als 'Heiliges Märtyrertum' gesammelt. Alle 3 Sek. wird 'Heiliges Märtyrertum' verbraucht und heilt 4 verletzte Verbündete innerhalb von 50 Metern um die verbrauchte Menge. Der Märtyrer selbst wird nicht geheilt.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[217965] = { ["name"] = "Reparaturset", ["text"] = "\"Das klimpernde Geräusch der losen Werkzeuge darin reicht schon aus, dass Ihr irgendetwas reparieren möchtet.\"" }
entries[217969] = { ["name"] = "Bombentrümmer", ["text"] = "\"Unglücklicherweise war sie noch scharf.\"\nVerkaufspreis:" }
entries[217983] = { ["name"] = "Rückzug", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nRückzug\nSpringt rückwärts, hebt alle bewegungseinschränkenden Effekte auf und erhöht 4 Sek. lang Eure Bewegungsgeschwindigkeit um 25%.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[217985] = { ["name"] = "Unvergessener goldener Greif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren unvergessenen goldenen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"In Sturmwind sind Löwen beliebt, und der Greif ist zur Hälfte Löwe. Deswegen sind diese Kreaturen ein wichtiger Bestandteil der Luftreisen durch die Gebiete der Allianz.\"\nVerkäufer:\nGedenker Amuul\nZone:\nDalaran\nKosten:\n25" }
entries[217986] = { ["name"] = "\"Köstliche\" Eibestandteile", ["text"] = "\"Koboldköche aus Lorenhall sind sich einig! Ohne diese Eier ist kein Gericht komplett.\"" }
entries[217987] = { ["name"] = "Unvergessener Windreiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren grünen Windreiter oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Hunderte Schlachten in Dutzenden Kampagnen wurden auf dem Rücken dieser geehrten Kreaturen bestritten und gewonnen.\"\nVerkäufer:\nGedenker Amuul\nZone:\nDalaran\nKosten:\n25" }
