entries[217996] = { ["name"] = "Zehnt der Sureki", ["text"] = "Questgegenstand\n\"Voller Geldmünzen und an die königlichen Tresorräume adressiert.\"" }
entries[217997] = { ["name"] = "Glitzerstein", ["text"] = "Questgegenstand\n\"Glitzert so, kann fast Gesicht erkennen!\"" }
entries[217998] = { ["name"] = "Süßfleisch", ["text"] = "Questgegenstand\n\"Lecker, lecker Larve! Süßes, schmackofatziges Fleisch!\"" }
entries[217999] = { ["name"] = "Leckere Muschel", ["text"] = "\"Aus dieser Muschel könnte man im Nu zahlreiche schmackhafte Gerichte zubereiten.\"" }
entries[218000] = { ["name"] = "Sack voller Gewürze", ["text"] = "\"Aus diesen Gewürzen könnte man köstliche Mahlzeiten zaubern, allerdings deutet der Staub um den Sack herum an, dass sie kaum zum Einsatz kamen.\"" }
entries[218002] = { ["name"] = "Unbezahlbarer Kürbis", ["text"] = "\"Dieser Kürbis verströmt einen entzückenden Duft.\"" }
entries[218003] = { ["name"] = "Glaubenssprung", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nGlaubenssprung\nZieht die Seele eines Gruppen- oder Schlachtzugsmitglieds zu Euch, sodass es sofort direkt vor Euch landet und seine Bewegungsgeschwindigkeit 3 Sek. lang um 40% erhöht wird.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[218004] = { ["name"] = "Verschwinden", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nVerschwinden\nErmöglicht es Euch, sofort zu verschwinden und so im Kampf 10 Sek. lang in den Verstohlenheitsmodus überzugehen. Schaden oder schädliche Effekte heben die Verstohlenheit nicht auf. Bewegungseinschränkende Effekte werden beim Verschwinden entfernt.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[218005] = { ["name"] = "Anstachelndes Gebrüll", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nAnstachelndes Gebrüll\nStößt ein wildes Brüllen aus, das 8 Sek. lang die Bewegungsgeschwindigkeit aller verbündeten Spielercharaktere innerhalb von 15 Metern um 60% erhöht.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
