entries[218042] = { ["name"] = "Rémy-Steuerung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Aktiviert Erntebot Remy auf dem Fungusfeld.\n\nSobald er aktiviert wurde, könnt Ihr Remy in Blüte des Lichts und in Schlüsselflammengebieten in der Nähe kontrollieren.\n\"Etwas, das Seraphine für Euch zusammengebaut hat.\"" }
