entries[218082] = { ["name"] = "Gunst des Geistwandlers", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nGunst des Geistwandlers\nEin Ruf nach Führung durch die Geister gestattet es 15 Sek. lang, Zauber aus der Bewegung heraus zu wirken. Kann während des Wirkens anderer Zauber gewirkt werden.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[218084] = { ["name"] = "Zusammengeknüllte Notiz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Ein um einen Schlüssel gewickelter Zettel, der bei Klaskins Leiche gefunden wurde.\"" }
entries[218085] = { ["name"] = "Phiole mit flüssigem Opal", ["text"] = "Questgegenstand\n\"Aufbewahrt in einer runengebundenen Flasche. Diese wabernde Flüssigkeit ist eine Mischung aus verschiedenen, seltenen flüssigen Mineralien, die in den Höhlen von Khaz Algar gefunden werden können.\"" }
entries[218086] = { ["name"] = "Unvergessene Flusspfote", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n80 ( 80)\nVerkaufspreis:" }
entries[218093] = { ["name"] = "<Händler-Reagenz A>", ["text"] = "\"DNT TEST IMPORT VENDOR REAGENT\"\nVerkaufspreis:" }
entries[218100] = { ["name"] = "Pläne: <Optionales Reagenz A>", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst der Dracheninseln (25)\n\"Lehrt Euch, wie man herstellt.\"\nVerkaufspreis:" }
entries[218101] = { ["name"] = "Pläne: <PVP-Legierung>", ["text"] = "Benötigt Schmiedekunst der Dracheninseln (25)\n\"Lehrt Euch, wie man herstellt.\"\nVerkaufspreis:" }
entries[218102] = { ["name"] = "Blutbefleckte Pläne: <PVP-Legierung>", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Schmiedekunst der Dracheninseln (25)\n\"Lehrt Euch, wie man herstellt. Diese Schriftrolle ist zu stark in Blut getränkt, um sie zu verkaufen oder mit ihr zu handeln.\"" }
entries[218103] = { ["name"] = "Pläne: <Endspiellegierung C>", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst der Dracheninseln (50)\n\"Lehrt Euch, wie man herstellt.\"\nVerkaufspreis:" }
entries[218105] = { ["name"] = "Klingensegen der Loa", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Schwert\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[218106] = { ["name"] = "Stillsteinfroschfalle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft eine Froschfalle auf den Boden, die 20 körperlichen Schaden verursacht, wenn ein Gegner darauf tritt, und diesen für 6 Sek. betäubt.\n\nKann beim Stillsteintümpel und in den umgebenden Gebieten verwendet werden. (10 Sek. Abklingzeit)" }
entries[218107] = { ["name"] = "Funkenkäferglas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Wenn Ihr das Glas schüttelt, beginnen die Funkenkäfer im Inneren schwach zu leuchten und die Umgebung ein wenig zu erhellen.\n\nMit diesem Licht könnt Ihr verborgene Gegenstände im Stillsteintümpel und Schlüsselflammengebieten in der Nähe finden. (15 Sek. Abklingzeit)\n\"Die leuchtenden, kleinen Käfer im Inneren sorgen für ein fantastisches, farbenfrohes Licht.\"" }
entries[218108] = { ["name"] = "Dunkler Pakt", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nDunkler Pakt\nOpfert 20% Eurer aktuellen Gesundheit, um Euch 20 Sek. lang in einen Schild zu hüllen, der Schaden in Höhe von 200% der geopferten Gesundheit absorbiert. Kann eingesetzt werden, während Ihr von Kontrollverlusteffekten betroffen seid.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[218109] = { ["name"] = "Unaufhaltsamer Tod", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nUnaufhaltsamer Tod\nEure Bewegungsgeschwindigkeit ist 10 Sek. lang um 35% erhöht. Ihr könnt nicht auf weniger als 100% Eurer normalen Geschwindigkeit verlangsamt werden und seid immun gegen externe Bewegungseffekte und Rückstöße.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[218110] = { ["name"] = "Seelengestalt", ["text"] = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nSeelengestalt\nVerwandelt Euch für 12 Sek. in einen Vulpin, teleportiert Euch 15 Meter vorwärts und erhöht Eure Bewegungsgeschwindigkeit um 50%. Ihr könnt 'Seelengestalt' alle paar Sekunden erneut aktivieren, um Euch noch einmal zu teleportieren.\n80 ( 80)\n\"Passt in einen Zahnradsockel.\"" }
entries[218111] = { ["name"] = "Zügel des Bernpterrordax", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Pterrordax könnte und würde Euch in Sekundenschnelle verspeisen. Ist es wirklich so eine gute Idee, auf ihm zu reiten?\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[218112] = { ["name"] = "Farbenfroher Strandstuhl", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Stellt einen farbenfrohen Strandstuhl auf. (5 Min Abklingzeit)\n\"Nach einem Bad im kühlen Nass gegen die Sommerhitze erwartet Euch herrliche Entspannung auf dieser harmonischen Farbkomposition, die an warme Sonnenuntergänge und Regenbögen erinnert.\"" }
entries[218113] = { ["name"] = "Süßstichgift", ["text"] = "Questgegenstand\nEinzigartig (20)\n\"Pikant und möglicherweise leicht süßlich, aber nicht zum Verzehr gedacht.\"" }
entries[218114] = { ["name"] = "Auge der Erweckung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt einem Gegenstand der Saison 4 von Dragonflight, der noch keinen Sockel besitzt, einen hinzu. Kann auf Helme, Armschienen, Gürtel und Ringe angewandt werden." }
